   where exercise.id = artwork.id
     and exercise.name = artwork.name
     and exercise.is_active is true
     and exercise.is_approved is true
     and (
       exercise.image_url is not distinct from artwork.old_image_url
       or exercise.image_url = artwork.new_image_url
     );

